using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class ProtectionResponsesForm:Form {
Project project;Circuit circuit;ComboBox kind;TextBox current,details;Label band;Panel plot;public bool Changed{get;private set;}
ResponseKind Kind{get{return (ResponseKind)kind.SelectedIndex;}}ResponseBinding Binding{get{return circuit.ProtectionResponses==null?null:circuit.ProtectionResponses.For(Kind);}}
public ProtectionResponsesForm(Project p,Circuit c){project=p;circuit=c;Text="Curvas de proteção — t-I, I²t e Ip";Size=new Size(1160,820);MinimumSize=new Size(1000,720);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=85,Padding=new Padding(8)};kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=205};kind.Items.AddRange(new object[]{"Tempo t-I (s)","Energia I²t (A²s)","Pico Ip (kA pico)"});kind.SelectedIndex=0;top.Controls.Add(kind);Add(top,"Importar curva CSV",Import);Add(top,"Exportar curva",Export);Add(top,"Modelo vazio",Template);Add(top,"Remover esta curva",Remove);top.SetFlowBreak(top.Controls[top.Controls.Count-1],true);top.Controls.Add(new Label{Text="Corrente consultada (A)",AutoSize=true,Margin=new Padding(4,8,4,0)});current=new TextBox{Width=150};top.Controls.Add(current);Add(top,"Consultar banda",RefreshBand);band=new Label{Dock=DockStyle.Top,Height=65,Padding=new Padding(10)};plot=new Panel{Dock=DockStyle.Fill,BackColor=Color.White};plot.Paint+=PaintCurve;details=new TextBox{Dock=DockStyle.Bottom,Height=220,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};Controls.Add(plot);Controls.Add(details);Controls.Add(band);Controls.Add(top);kind.SelectedIndexChanged+=delegate{RefreshCurve();};Shown+=delegate{details.SelectionStart=0;details.SelectionLength=0;details.ScrollToCaret();current.Focus();};Resize+=delegate{plot.Invalidate();};RefreshCurve();}
void Add(FlowLayoutPanel panel,string label,Action action){var button=new Button{Text=label,AutoSize=true};button.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Curvas",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(button);}
void RefreshCurve(){var bind=Binding;if(bind!=null){var pts=bind.Curve.Points;current.Text=Math.Exp((Math.Log(pts[0].CurrentA)+Math.Log(pts[pts.Count-1].CurrentA))/2).ToString("G12",CultureInfo.CurrentCulture);}else current.Text="1000";details.Text=ProtectionResponses.Describe(project,circuit);RefreshBand();}
double? Query(){double value;return Double.TryParse(current.Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)&&!Double.IsNaN(value)&&!Double.IsInfinity(value)&&value>0&&value<=1e15?(double?)value:null;}
void RefreshBand(){var bind=Binding;double? value=Query();if(bind==null)band.Text="Curva não informada. Importe pontos e metadados da fonte técnica; nenhum envelope OEM é fornecido.";else if(!value.HasValue)band.Text="Informe uma corrente positiva e finita em A.";else{var pt=bind.Curve.At(value.Value);band.Text=(pt==null?"Fora do domínio declarado; sem extrapolação.":"Banda a "+value.Value.ToString("G8",CultureInfo.CurrentCulture)+" A: "+pt.Lower.ToString("G8",CultureInfo.CurrentCulture)+" até "+pt.Upper.ToString("G8",CultureInfo.CurrentCulture)+" "+ProtectionResponses.Unit(Kind)+".")+"\r\n"+(ProtectionResponses.Matches(project,circuit,bind)?"Identidade/contexto nominal correspondem; confira ajustes e condições da ficha.":"Referência sem vínculo nominal atual; o gráfico mostra somente os dados importados.");}plot.Invalidate();}
void Import(){using(var d=new OpenFileDialog{Filter="CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var curve=ProtectionResponses.Import(d.FileName);ProtectionResponses.Attach(project,circuit,curve);Changed=true;kind.SelectedIndex=(int)curve.Kind;RefreshCurve();}}
void Export(){if(Binding==null)throw new InvalidOperationException("Não há curva selecionada.");using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="curva-"+Kind+".csv"})if(d.ShowDialog(this)==DialogResult.OK)ProtectionResponses.Export(Binding.Curve,d.FileName);}
void Template(){using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="modelo-curva-resposta.csv"})if(d.ShowDialog(this)==DialogResult.OK)ProtectionResponses.Export(null,d.FileName);}
void Remove(){if(circuit.ProtectionResponses==null)return;var candidate=circuit.ProtectionResponses.Copy();candidate.Set(Kind,null);circuit.ProtectionResponses=candidate.Time==null&&candidate.Energy==null&&candidate.Peak==null?null:candidate;Changed=true;RefreshCurve();}
void PaintCurve(object sender,PaintEventArgs e){var bind=Binding;var g=e.Graphics;g.Clear(Color.White);if(bind==null)return;var curve=bind.Curve;var pts=curve.Points;float left=80,top=35,right=Math.Max(left+1,plot.ClientSize.Width-35),bottom=Math.Max(top+1,plot.ClientSize.Height-60);double x0=Math.Log10(pts[0].CurrentA),x1=Math.Log10(pts[pts.Count-1].CurrentA),y0=Math.Log10(pts.Min(x=>x.Lower)),y1=Math.Log10(pts.Max(x=>x.Upper));if(y1-y0<1e-9){y0-=.5;y1+=.5;}Func<double,double,PointF> pos=(x,y)=>new PointF((float)(left+(Math.Log10(x)-x0)/(x1-x0)*(right-left)),(float)(bottom-(Math.Log10(y)-y0)/(y1-y0)*(bottom-top)));using(var gridPen=new Pen(Color.Gainsboro)){for(int i=0;i<=4;i++){float x=left+(right-left)*i/4,y=top+(bottom-top)*i/4;g.DrawLine(gridPen,x,top,x,bottom);g.DrawLine(gridPen,left,y,right,y);g.DrawString(Math.Pow(10,x0+(x1-x0)*i/4).ToString("G3",CultureInfo.CurrentCulture),Font,Brushes.Black,x-15,bottom+8);g.DrawString(Math.Pow(10,y1-(y1-y0)*i/4).ToString("G3",CultureInfo.CurrentCulture),Font,Brushes.Black,5,y-8);}}g.DrawRectangle(Pens.Gray,left,top,right-left,bottom-top);using(var lower=new Pen(Color.RoyalBlue,2))using(var upper=new Pen(Color.DarkOrange,2)){g.DrawLines(lower,pts.Select(x=>pos(x.CurrentA,x.Lower)).ToArray());g.DrawLines(upper,pts.Select(x=>pos(x.CurrentA,x.Upper)).ToArray());}g.DrawString(ProtectionResponses.Title(Kind)+" — "+ProtectionResponses.Unit(Kind)+"; banda inferior azul / superior laranja; eixos logarítmicos",Font,Brushes.Black,left,4);g.DrawString("Corrente (A)",Font,Brushes.Black,(left+right)/2-40,bottom+30);var query=Query();if(query.HasValue&&query.Value>=pts[0].CurrentA&&query.Value<=pts[pts.Count-1].CurrentA){float x=pos(query.Value,pts[0].Lower).X;using(var line=new Pen(Color.Gray)){line.DashStyle=System.Drawing.Drawing2D.DashStyle.Dash;g.DrawLine(line,x,top,x,bottom);}}}
}
partial class Studio{void ConfigureProtectionResponses(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new ProtectionResponsesForm(project,circuit)){form.ShowDialog(this);if(form.Changed){Change();tabs.SelectedTab=studyPage;}}}}
}
